def _read_auth_tokens():
    return [token for token in (READ_ACCESS_TOKEN, ADMIN_DEBUG_TOKEN) if token]


def _request_read_token(request: Request):
    header_token = request.headers.get("X-Stock-Ultimus-Read-Token")
    if header_token:
        return header_token
    gpt_action_token = request.headers.get("X-Api-Key")
    if gpt_action_token:
        return gpt_action_token
    cookie_token = request.cookies.get("stock_ultimus_read_token")
    if cookie_token:
        return cookie_token
    admin_token = request.headers.get("X-Admin-Debug-Token")
    if admin_token:
        return admin_token
    authorization = request.headers.get("Authorization", "")
    if authorization.lower().startswith("bearer "):
        return authorization.split(" ", 1)[1].strip()
    return None


def _path_requires_read_auth(path):
    if not REQUIRE_READ_AUTH:
        return False
    if path in READ_AUTH_PUBLIC_PATHS:
        return False
    if any(path.startswith(prefix) for prefix in READ_AUTH_PUBLIC_PREFIXES):
        return False
    return any(path.startswith(prefix) for prefix in READ_AUTH_SENSITIVE_PREFIXES)


def _read_auth_login_redirect(request: Request):
    if request.method.upper() != "GET":
        return None
    path = request.url.path
    if not any(path.startswith(prefix) for prefix in READ_AUTH_BROWSER_LOGIN_PREFIXES):
        return None
    next_path = path
    if request.url.query:
        next_path = "{}?{}".format(path, request.url.query)
    login_url = "/read_auth_login?{}".format(urllib.parse.urlencode({"next": next_path}))
    return RedirectResponse(url=login_url, status_code=303)


@app.middleware("http")
async def sensitive_read_auth_middleware(request: Request, call_next):
    if _path_requires_read_auth(request.url.path):
        allowed_tokens = _read_auth_tokens()
        if not allowed_tokens:
            return JSONResponse(
                status_code=503,
                content={
                    "detail": "Read auth is required but no read token is configured.",
                    "not_order_instruction": True,
                },
            )
        request_token = _request_read_token(request)
        if not request_token or not any(hmac.compare_digest(str(request_token), str(token)) for token in allowed_tokens):
            redirect = _read_auth_login_redirect(request)
            if redirect is not None:
                return redirect
            return JSONResponse(
                status_code=401,
                content={
                    "detail": "Read token required.",
                    "not_order_instruction": True,
                },
            )
    return await call_next(request)


def _read_auth_token_valid(token):
    if not token:
        return False
    return any(hmac.compare_digest(str(token), str(allowed)) for allowed in _read_auth_tokens())


