# TradingView Technical Snapshot Normalizer
# ============================================================

BOOLEAN_NUMERIC_FIELDS_V15_1 = [
    "range_20d",
    "range_breakout",
    "support_near",
    "resistance_near",
    "earnings_soon",
    "event_risk",
    "ex_dividend_soon",
    "assignment_acceptable",
]

NUMERIC_FIELDS_V15_1 = [
    "price",
    "score",
    "rsi",
    "adx",
    "volume_relative",
    "iv_rank",
    "iv_percentile",
    "trend_code",
    "vwap_position_code",
]


def normalize_numeric_bool(value):
    if value is None:
        return None

    if isinstance(value, bool):
        return value

    try:
        if isinstance(value, str):
            v = value.strip().lower()
            if v in ["true", "yes", "y", "si", "sí"]:
                return True
            if v in ["false", "no", "n"]:
                return False
            if v in ["1", "1.0"]:
                return True
            if v in ["0", "0.0"]:
                return False

        n = float(value)
        if math.isnan(n) or math.isinf(n):
            return None
        return n >= 0.5

    except Exception:
        return None


def normalize_number_or_none(value):
    if value is None:
        return None

    try:
        if isinstance(value, str):
            value = value.strip()
            if value.lower() in ["na", "nan", "none", "null", ""]:
                return None

        n = float(value)
        if math.isnan(n) or math.isinf(n):
            return None

        return round(n, 6)

    except Exception:
        return None


def normalize_trend_code(value):
    n = normalize_number_or_none(value)

    if n is None:
        return None

    if n > 0:
        return "bullish"

    if n < 0:
        return "bearish"

    return "neutral"


def normalize_vwap_position_code(value):
    n = normalize_number_or_none(value)

    if n is None:
        return None

    if n > 0:
        return "above"

    if n < 0:
        return "below"

    return "near"


def normalize_technical_snapshot_payload(payload):
    payload = dict(payload or {})

    strategy_context = str(payload.get("strategy_context") or "").upper().strip()
    strategy = str(payload.get("strategy") or "").upper().strip()
    if not strategy and strategy_context:
        payload["strategy"] = strategy_context
    if not strategy_context and strategy:
        payload["strategy_context"] = strategy

    source = str(payload.get("source") or payload.get("original_source") or "").upper().strip()
    action = str(payload.get("action") or "").upper().strip()
    if source == "TRADINGVIEW" and action == "ALERT_ONLY":
        payload["not_order_instruction"] = True
        payload["execution_authorized"] = False

    for key in NUMERIC_FIELDS_V15_1:
        if key in payload:
            payload[key] = normalize_number_or_none(payload.get(key))

    for key in BOOLEAN_NUMERIC_FIELDS_V15_1:
        if key in payload:
            payload[key] = normalize_numeric_bool(payload.get(key))

    if payload.get("trend") in [None, "", "null"]:
        trend = normalize_trend_code(payload.get("trend_code"))
        if trend:
            payload["trend"] = trend

    if payload.get("vwap_position") in [None, "", "null"]:
        vwap_position = normalize_vwap_position_code(payload.get("vwap_position_code"))
        if vwap_position:
            payload["vwap_position"] = vwap_position

    payload["normalizer_version"] = "v15.1"
    payload["normalized_at"] = now_utc().isoformat()

    return payload


