def _v31_normalize_state(state):
    state = _v29_safe_upper(state, "NO_DATA")
    aliases = {
        "WAIT_MARKET_OPEN": "WAIT_MARKET",
        "MARKET_CLOSED_OR_NOT_LIQUID_YET": "WAIT_MARKET",
        "WAIT_LIQUIDITY": "WAIT_MARKET",
        "WAIT_TECHNICAL_DATA": "WAIT_TECHNICAL",
        "WAIT_TECHNICAL_CONFIRMATION": "WAIT_TECHNICAL",
        "ENTRY_READY_WITH_MARKET_CHECK": "MANUAL_REVIEW",
        "RADAR": "MANUAL_REVIEW",
    }
    return aliases.get(state, state)


def _v31_status_from_v29(d, key):
    state = _v31_normalize_state(d.get("final_state"))

    if key == "risk":
        if state == "RISK_BLOCKED":
            return "RISK_BLOCKED"
        if state in ["NO_DATA", "WAIT_ACCOUNT_CONTEXT", "WAIT_MARKET", "WAIT_OPTIONS_DATA", "WAIT_TECHNICAL"]:
            return "NOT_EVALUATED"
        return "PASS"

    if key == "portfolio":
        if state in ["NO_DATA", "WAIT_ACCOUNT_CONTEXT", "WAIT_MARKET", "WAIT_OPTIONS_DATA", "WAIT_TECHNICAL"]:
            return "NOT_EVALUATED"
        return "PASS"

    if key == "technical":
        if state == "WAIT_TECHNICAL":
            return "WAIT_TECHNICAL"
        if (d.get("technical") or {}).get("confirmed") is True:
            return "CONFIRMED"
        if (d.get("technical") or {}).get("available") is True:
            return "AVAILABLE_NOT_CONFIRMED"
        return "MISSING"

    if key == "construction":
        if state == "WAIT_OPTIONS_DATA":
            return "WAIT_OPTIONS_DATA"
        if d.get("selected_contract"):
            return "CONTRACT_SELECTED"
        return "MISSING"

    return "UNKNOWN"


def _v31_blockers_from_v29(d):
    state = _v31_normalize_state(d.get("final_state"))
    blockers = []

    primary = d.get("main_blocker")
    if primary:
        blockers.append(primary)

    if state == "NO_DATA":
        blockers.append("NO_DATA")
    elif state == "WAIT_MARKET":
        blockers.append("WAIT_MARKET")
    elif state == "WAIT_ACCOUNT_CONTEXT":
        blockers.append("WAIT_ACCOUNT_CONTEXT")
    elif state == "WAIT_OPTIONS_DATA":
        blockers.append("WAIT_OPTIONS_DATA")
        for field in d.get("required_missing_fields") or []:
            blockers.append(f"MISSING_{str(field).upper()}")
    elif state == "WAIT_TECHNICAL":
        blockers.append("WAIT_TECHNICAL")
    elif state == "RISK_BLOCKED":
        blockers.append("RISK_BLOCKED")
    elif state == "MANUAL_REVIEW":
        blockers.append("MANUAL_REVIEW")

    if state == "ENTRY_READY":
        return []

    deduped = []
    for blocker in blockers:
        if blocker and blocker not in deduped:
            deduped.append(blocker)
    return deduped


def _v31_main_blocker(state, blockers):
    if state == "ENTRY_READY":
        return None

    priority = [
        "NO_DATA",
        "WAIT_ACCOUNT_CONTEXT",
        "WAIT_MARKET",
        "WAIT_OPTIONS_DATA",
        "WAIT_TECHNICAL",
        "RISK_BLOCKED",
        "MANUAL_REVIEW",
    ]

    for item in priority:
        if item == state or item in blockers:
            return item

    return blockers[0] if blockers else state


def _v31_strategy_version(d):
    strategy = _v29_safe_upper(d.get("strategy"), "UNKNOWN")
    if "COVERED" in strategy and "CALL" in strategy:
        return "covered_calls_v31_manual_review"
    if "PUT" in strategy:
        return "cash_secured_puts_v31_manual_review"
    if "INTRADAY" in strategy or "FUTURES" in strategy:
        return "intraday_index_futures_v31_manual_review"
    return "strategy_v31_manual_review"


def _v31_ticker_risk_context(decision):
    market = dict(decision.get("market") or {})
    technical = decision.get("technical") if isinstance(decision.get("technical"), dict) else {}
    raw = technical.get("raw") if isinstance(technical.get("raw"), dict) else {}

    for key in [
        "earnings_soon",
        "event_risk",
        "ex_dividend_soon",
        "assignment_acceptable",
    ]:
        if raw.get(key) is not None:
            market[key] = raw.get(key)

    return market


def _v31_env_float(name, default):
    try:
        value = os.getenv(name, "")
        if str(value).strip() == "":
            return default
        return float(value)
    except Exception:
        return default


def _v31_env_int(name, default):
    try:
        value = os.getenv(name, "")
        if str(value).strip() == "":
            return default
        return int(value)
    except Exception:
        return default


def _v31_active_risk_profile_name():
    return _v29_safe_upper(os.getenv("V31_RISK_PROFILE_PRESET", "balanced"), "BALANCED").lower()


def _v31_risk_profile_preset(name=None):
    key = _v29_safe_upper(name or _v31_active_risk_profile_name(), "BALANCED").lower()
    if key not in _V31_RISK_PROFILE_PRESETS:
        key = "balanced"
    return key, dict(_V31_RISK_PROFILE_PRESETS[key])


def _v31_risk_profile(name=None):
    """Runtime-tunable risk profile for manual-review readiness.

    Defaults are intentionally close to the existing V29 quality gate so this
    layer tightens or documents risk without weakening WAIT_OPTIONS_DATA or
    creating any path to automatic execution.
    """
    allowed_strategies = [
        item.strip().upper()
        for item in os.getenv("V31_ALLOWED_STRATEGIES", "").split(",")
        if item.strip()
    ]
    blocked_tickers = [
        item.strip().upper()
        for item in os.getenv("V31_BLOCKED_TICKERS", "").split(",")
        if item.strip()
    ]
    preset_name, preset = _v31_risk_profile_preset(name)
    return {
        "profile_version": "v31_risk_profile_v1",
        "preset": preset_name,
        "available_presets": sorted(_V31_RISK_PROFILE_PRESETS.keys()),
        "profile_name": os.getenv("V31_RISK_PROFILE_NAME", preset["profile_name"]),
        "min_dte": _v31_env_int("V31_MIN_DTE", preset["min_dte"]),
        "max_dte": _v31_env_int("V31_MAX_DTE", preset["max_dte"]),
        "min_abs_delta": _v31_env_float("V31_MIN_ABS_DELTA", preset["min_abs_delta"]),
        "max_abs_delta": _v31_env_float("V31_MAX_ABS_DELTA", preset["max_abs_delta"]),
        "max_spread_pct": _v31_env_float("V31_MAX_SPREAD_PCT", preset["max_spread_pct"]),
        "max_abs_spread": _v31_env_float("V31_MAX_ABS_SPREAD", preset["max_abs_spread"]),
        "min_bid": _v31_env_float("V31_MIN_BID", preset["min_bid"]),
        "min_option_score": _v31_env_float("V31_MIN_OPTION_SCORE", preset["min_option_score"]),
        "min_technical_score": _v31_env_float("V31_MIN_TECH_SCORE", preset["min_technical_score"]),
        "min_iv_for_premium_selling": _v31_env_float("V31_MIN_IV_FOR_PREMIUM_SELLING", preset["min_iv_for_premium_selling"]),
        "min_iv_rank_for_premium_selling": _v31_env_float("V31_MIN_IV_RANK_FOR_PREMIUM_SELLING", preset["min_iv_rank_for_premium_selling"]),
        "min_iv_hv_spread_for_premium_selling": _v31_env_float("V31_MIN_IV_HV_SPREAD_FOR_PREMIUM_SELLING", preset["min_iv_hv_spread_for_premium_selling"]),
        "allowed_strategies": allowed_strategies,
        "blocked_tickers": blocked_tickers,
        "not_order_instruction": True,
    }


def _v31_profile_value(value):
    return _v29_safe_float(value, None)


def _v31_risk_check(name, field, value, comparator, limit, blocked, note):
    return {
        "name": name,
        "field": field,
        "value": value,
        "comparator": comparator,
        "limit": limit,
        "status": "BLOCKED" if blocked else "PASS",
        "note": note,
    }


def _v31_evaluate_risk_profile(decision, profile=None):
    profile = profile or _v31_risk_profile()
    contract = decision.get("selected_contract") or {}
    strategy = _v29_safe_upper(decision.get("strategy"), "UNKNOWN")
    ticker = _v29_safe_upper(decision.get("ticker"), "UNKNOWN")
    blockers = []
    notes = []
    checks = []

    if profile.get("allowed_strategies") and strategy not in profile["allowed_strategies"]:
        blockers.append("RISK_PROFILE_STRATEGY_NOT_ALLOWED")
        checks.append(_v31_risk_check(
            "RISK_PROFILE_STRATEGY_NOT_ALLOWED",
            "strategy",
            strategy,
            "in",
            profile.get("allowed_strategies"),
            True,
            "Strategy is not enabled in the active V31 risk profile.",
        ))
    if ticker in (profile.get("blocked_tickers") or []):
        blockers.append("RISK_PROFILE_TICKER_BLOCKED")
        checks.append(_v31_risk_check(
            "RISK_PROFILE_TICKER_BLOCKED",
            "ticker",
            ticker,
            "not_in",
            profile.get("blocked_tickers"),
            True,
            "Ticker is explicitly blocked by the active V31 risk profile.",
        ))

    dte = _v31_profile_value(contract.get("dte"))
    if dte is not None:
        if dte < profile["min_dte"]:
            blockers.append("RISK_PROFILE_DTE_TOO_LOW")
            checks.append(_v31_risk_check(
                "RISK_PROFILE_DTE_TOO_LOW",
                "selected_contract.dte",
                dte,
                ">=",
                profile["min_dte"],
                True,
                "Contract DTE is below the profile minimum.",
            ))
        if dte > profile["max_dte"]:
            blockers.append("RISK_PROFILE_DTE_TOO_HIGH")
            checks.append(_v31_risk_check(
                "RISK_PROFILE_DTE_TOO_HIGH",
                "selected_contract.dte",
                dte,
                "<=",
                profile["max_dte"],
                True,
                "Contract DTE is above the profile maximum.",
            ))

    delta = _v31_profile_value(contract.get("delta"))
    if delta is not None:
        abs_delta = abs(delta)
        if abs_delta < profile["min_abs_delta"]:
            blockers.append("RISK_PROFILE_DELTA_TOO_LOW")
            checks.append(_v31_risk_check(
                "RISK_PROFILE_DELTA_TOO_LOW",
                "selected_contract.abs_delta",
                round(abs_delta, 6),
                ">=",
                profile["min_abs_delta"],
                True,
                "Absolute delta is below the profile range.",
            ))
        if abs_delta > profile["max_abs_delta"]:
            blockers.append("RISK_PROFILE_DELTA_TOO_HIGH")
            checks.append(_v31_risk_check(
                "RISK_PROFILE_DELTA_TOO_HIGH",
                "selected_contract.abs_delta",
                round(abs_delta, 6),
                "<=",
                profile["max_abs_delta"],
                True,
                "Absolute delta is above the profile range.",
            ))

    spread = _v31_profile_value(contract.get("spread"))
    spread_pct = _v31_profile_value(contract.get("spread_pct"))
    if spread is not None and spread > profile["max_abs_spread"]:
        blockers.append("RISK_PROFILE_SPREAD_TOO_WIDE")
        checks.append(_v31_risk_check(
            "RISK_PROFILE_SPREAD_TOO_WIDE",
            "selected_contract.spread",
            spread,
            "<=",
            profile["max_abs_spread"],
            True,
            "Absolute bid/ask spread is wider than the profile allows.",
        ))
    if spread_pct is not None and spread_pct > profile["max_spread_pct"]:
        blockers.append("RISK_PROFILE_SPREAD_PCT_TOO_WIDE")
        checks.append(_v31_risk_check(
            "RISK_PROFILE_SPREAD_PCT_TOO_WIDE",
            "selected_contract.spread_pct",
            spread_pct,
            "<=",
            profile["max_spread_pct"],
            True,
            "Bid/ask spread percentage is wider than the profile allows.",
        ))

    bid = _v31_profile_value(contract.get("bid"))
    if bid is not None and bid < profile["min_bid"]:
        blockers.append("RISK_PROFILE_BID_TOO_LOW")
        checks.append(_v31_risk_check(
            "RISK_PROFILE_BID_TOO_LOW",
            "selected_contract.bid",
            bid,
            ">=",
            profile["min_bid"],
            True,
            "Bid is below the minimum executable premium threshold.",
        ))

    premium_selling_strategy = strategy in {"NAKED_PUT", "CASH_SECURED_PUT", "SHORT_PUT", "PUT_SELL"}
    volatility_context = contract.get("volatility_context") if isinstance(contract.get("volatility_context"), dict) else {}
    iv = _v31_profile_value(contract.get("iv") or contract.get("implied_volatility") or volatility_context.get("iv"))
    iv_rank = _v31_profile_value(
        contract.get("iv_rank")
        or contract.get("ivr")
        or contract.get("iv_percentile")
        or volatility_context.get("iv_rank")
    )
    iv_hv_spread = _v31_profile_value(
        contract.get("iv_hv_spread")
        or contract.get("iv_minus_hv")
        or volatility_context.get("iv_hv_spread")
    )
    if premium_selling_strategy:
        if iv_rank is not None:
            if iv_rank < profile["min_iv_rank_for_premium_selling"]:
                blockers.append("RISK_PROFILE_VOLATILITY_PREMIUM_TOO_LOW")
                checks.append(_v31_risk_check(
                    "RISK_PROFILE_VOLATILITY_PREMIUM_TOO_LOW",
                    "selected_contract.iv_rank",
                    iv_rank,
                    ">=",
                    profile["min_iv_rank_for_premium_selling"],
                    True,
                    "IV rank/percentile is too low for premium selling.",
                ))
        elif iv_hv_spread is not None:
            if iv_hv_spread < profile["min_iv_hv_spread_for_premium_selling"]:
                blockers.append("RISK_PROFILE_VOLATILITY_PREMIUM_TOO_LOW")
                checks.append(_v31_risk_check(
                    "RISK_PROFILE_VOLATILITY_PREMIUM_TOO_LOW",
                    "selected_contract.iv_hv_spread",
                    iv_hv_spread,
                    ">=",
                    profile["min_iv_hv_spread_for_premium_selling"],
                    True,
                    "Implied volatility is not sufficiently above realized/historical volatility.",
                ))
        elif iv is not None:
            if iv < profile["min_iv_for_premium_selling"]:
                blockers.append("RISK_PROFILE_VOLATILITY_PREMIUM_TOO_LOW")
                checks.append(_v31_risk_check(
                    "RISK_PROFILE_VOLATILITY_PREMIUM_TOO_LOW",
                    "selected_contract.iv",
                    iv,
                    ">=",
                    profile["min_iv_for_premium_selling"],
                    True,
                    "Absolute IV is too low; option premium may be cheap for selling.",
                ))
        else:
            blockers.append("RISK_PROFILE_VOLATILITY_PREMIUM_MISSING")
            checks.append(_v31_risk_check(
                "RISK_PROFILE_VOLATILITY_PREMIUM_MISSING",
                "selected_contract.iv",
                None,
                "present",
                profile["min_iv_for_premium_selling"],
                True,
                "No IV, IV rank, or IV/HV spread is available to confirm premium richness.",
            ))

    option_score = _v31_profile_value(decision.get("source_decision", {}).get("options_score") or decision.get("options_score"))
    if option_score is not None and option_score < profile["min_option_score"]:
        blockers.append("RISK_PROFILE_OPTION_SCORE_TOO_LOW")
        checks.append(_v31_risk_check(
            "RISK_PROFILE_OPTION_SCORE_TOO_LOW",
            "options_score",
            option_score,
            ">=",
            profile["min_option_score"],
            True,
            "Option score is below the active profile minimum.",
        ))

    technical_score = _v31_profile_value(decision.get("technical", {}).get("score") if isinstance(decision.get("technical"), dict) else None)
    if technical_score is not None and technical_score < profile["min_technical_score"]:
        blockers.append("RISK_PROFILE_TECH_SCORE_TOO_LOW")
        checks.append(_v31_risk_check(
            "RISK_PROFILE_TECH_SCORE_TOO_LOW",
            "technical.score",
            technical_score,
            ">=",
            profile["min_technical_score"],
            True,
            "Technical score is below the active profile minimum.",
        ))

    strategy_guard = _V31_STRATEGY_RISK_GUARDS.get(strategy)
    if strategy_guard:
        if dte is not None:
            if dte < strategy_guard["min_dte"] and "RISK_PROFILE_DTE_TOO_LOW" not in blockers:
                blockers.append("RISK_PROFILE_DTE_TOO_LOW")
                checks.append(_v31_risk_check(
                    "RISK_PROFILE_DTE_TOO_LOW",
                    "selected_contract.dte",
                    dte,
                    ">=",
                    strategy_guard["min_dte"],
                    True,
                    "Contract DTE is below the strategy-specific manual-review minimum.",
                ))
            if dte > strategy_guard["max_dte"] and "RISK_PROFILE_DTE_TOO_HIGH" not in blockers:
                blockers.append("RISK_PROFILE_DTE_TOO_HIGH")
                checks.append(_v31_risk_check(
                    "RISK_PROFILE_DTE_TOO_HIGH",
                    "selected_contract.dte",
                    dte,
                    "<=",
                    strategy_guard["max_dte"],
                    True,
                    "Contract DTE is above the strategy-specific manual-review maximum.",
                ))
        if delta is not None:
            abs_delta = abs(delta)
            if abs_delta < strategy_guard["min_abs_delta"] and "RISK_PROFILE_DELTA_TOO_LOW" not in blockers:
                blockers.append("RISK_PROFILE_DELTA_TOO_LOW")
                checks.append(_v31_risk_check(
                    "RISK_PROFILE_DELTA_TOO_LOW",
                    "selected_contract.abs_delta",
                    round(abs_delta, 6),
                    ">=",
                    strategy_guard["min_abs_delta"],
                    True,
                    "Absolute delta is below the strategy-specific manual-review range.",
                ))
            if abs_delta > strategy_guard["max_abs_delta"] and "RISK_PROFILE_DELTA_TOO_HIGH" not in blockers:
                blockers.append("RISK_PROFILE_DELTA_TOO_HIGH")
                checks.append(_v31_risk_check(
                    "RISK_PROFILE_DELTA_TOO_HIGH",
                    "selected_contract.abs_delta",
                    round(abs_delta, 6),
                    "<=",
                    strategy_guard["max_abs_delta"],
                    True,
                    "Absolute delta is above the strategy-specific manual-review range.",
                ))
        if spread_pct is not None and spread_pct > strategy_guard["max_spread_pct"] and "RISK_PROFILE_SPREAD_PCT_TOO_WIDE" not in blockers:
            blockers.append("RISK_PROFILE_SPREAD_PCT_TOO_WIDE")
            checks.append(_v31_risk_check(
                "RISK_PROFILE_SPREAD_PCT_TOO_WIDE",
                "selected_contract.spread_pct",
                spread_pct,
                "<=",
                strategy_guard["max_spread_pct"],
                True,
                "Bid/ask spread percentage is wider than the strategy-specific manual-review maximum.",
            ))
        if bid is not None and bid < strategy_guard["min_bid"] and "RISK_PROFILE_BID_TOO_LOW" not in blockers:
            blockers.append("RISK_PROFILE_BID_TOO_LOW")
            checks.append(_v31_risk_check(
                "RISK_PROFILE_BID_TOO_LOW",
                "selected_contract.bid",
                bid,
                ">=",
                strategy_guard["min_bid"],
                True,
                "Bid is below the strategy-specific executable premium floor.",
            ))

    if blockers:
        notes.append("Risk profile blocked manual-review readiness; no execution is authorized.")
    else:
        notes.append("Risk profile passed for manual-review readiness only.")

    deduped = []
    for blocker in blockers:
        if blocker not in deduped:
            deduped.append(blocker)

    return {
        "profile": profile,
        "status": "BLOCKED" if deduped else "PASS",
        "primary_blocker": deduped[0] if deduped else None,
        "blockers": deduped,
        "blocked_checks": checks,
        "notes": notes,
        "not_order_instruction": True,
    }


def _v31_apply_risk_profile_gate(decision):
    risk_profile = _v31_evaluate_risk_profile(decision)
    decision["risk_profile"] = risk_profile
    if decision.get("final_state") == "ENTRY_READY" and risk_profile["status"] == "BLOCKED":
        blockers = list(decision.get("blockers") or [])
        blockers.extend(risk_profile["blockers"])
        deduped = []
        for blocker in blockers:
            if blocker and blocker not in deduped:
                deduped.append(blocker)
        decision["final_state"] = "RISK_BLOCKED"
        decision["decision"] = "RISK_BLOCKED"
        decision["main_blocker"] = "RISK_BLOCKED"
        decision["blockers"] = deduped or ["RISK_BLOCKED"]
        decision["risk_blocker"] = risk_profile.get("primary_blocker")
        decision["risk_blocked_details"] = risk_profile.get("blocked_checks") or []
        decision["manual_review_ready"] = False
        decision["risk_status"] = "RISK_BLOCKED"
        first_detail = (decision["risk_blocked_details"] or [{}])[0]
        detail_text = ""
        if first_detail:
            detail_text = (
                f" Motivo principal: {first_detail.get('name')} "
                f"({first_detail.get('field')}={first_detail.get('value')} "
                f"requiere {first_detail.get('comparator')} {first_detail.get('limit')})."
            )
        decision["explanation"] = (
            f"{decision.get('ticker')}: RISK_BLOCKED por perfil de riesgo V31. "
            "Revisar risk_profile.blockers antes de considerar revision manual."
            f"{detail_text}"
        )
    return decision


def _v31_apply_event_assignment_gate(decision):
    if decision.get("final_state") != "ENTRY_READY":
        return decision

    market = _v31_ticker_risk_context(decision)
    strategy = _v29_safe_upper(decision.get("strategy"), "UNKNOWN")
    blockers = list(decision.get("blockers") or [])
    triggered = []

    if bool(market.get("earnings_soon")) and "EARNINGS_SOON" not in blockers:
        blockers.append("EARNINGS_SOON")
        triggered.append("EARNINGS_SOON")
    if bool(market.get("event_risk")) and "EVENT_RISK_ACTIVE" not in blockers:
        blockers.append("EVENT_RISK_ACTIVE")
        triggered.append("EVENT_RISK_ACTIVE")
    if strategy == "COVERED_CALL" and bool(market.get("ex_dividend_soon")) and "EX_DIVIDEND_WITHIN_WINDOW" not in blockers:
        blockers.append("EX_DIVIDEND_WITHIN_WINDOW")
        triggered.append("EX_DIVIDEND_WITHIN_WINDOW")
    if strategy in {"COVERED_CALL", "NAKED_PUT", "CASH_SECURED_PUT"} and market.get("assignment_acceptable") is False and "ASSIGNMENT_UNACCEPTABLE" not in blockers:
        blockers.append("ASSIGNMENT_UNACCEPTABLE")
        triggered.append("ASSIGNMENT_UNACCEPTABLE")

    if not triggered:
        decision["market"] = market
        return decision

    decision["market"] = market
    decision["final_state"] = "RISK_BLOCKED"
    decision["decision"] = "RISK_BLOCKED"
    decision["main_blocker"] = "RISK_BLOCKED"
    decision["risk_blocker"] = triggered[0]
    decision["blockers"] = blockers
    decision["manual_review_ready"] = False
    decision["risk_status"] = "RISK_BLOCKED"
    decision["explanation"] = (
        f"{decision.get('ticker')}: RISK_BLOCKED por riesgo de evento/assignment "
        f"({', '.join(triggered)})."
    )
    return decision


def _v31_broker_check_for_decision(decision):
    master = _v29_discover_master_snapshot()
    snapshot = master.get("data") if isinstance(master.get("data"), dict) else {}
    return shared_broker_check.broker_check_for_ticker(
        snapshot,
        decision.get("ticker"),
        decision.get("strategy"),
    )


def _v31_broker_check_max_age_minutes():
    return _v31_env_int("V31_BROKER_CHECK_MAX_AGE_MINUTES", shared_broker_check.DEFAULT_BROKER_CHECK_MAX_AGE_MINUTES)


def _v31_broker_check_freshness(broker):
    return shared_broker_check.broker_check_freshness(
        broker if isinstance(broker, dict) else {},
        max_age_minutes=_v31_broker_check_max_age_minutes(),
    )


def _v31_apply_broker_check_gate(decision):
    broker = _v31_broker_check_for_decision(decision)
    if isinstance(broker, dict):
        decision["broker_check"] = broker
    else:
        decision["broker_check"] = {
            "broker_check_version": shared_broker_check.BROKER_CHECK_VERSION,
            "ticker": decision.get("ticker"),
            "strategy": decision.get("strategy"),
            "status": "UNKNOWN",
            "ok_for_manual_review": True,
            "blockers": [],
            "warnings": ["BROKER_CHECK_NOT_AVAILABLE_IN_SNAPSHOT"],
            "manual_broker_ticket_still_required": True,
            "execution_authorized": False,
            "not_order_instruction": True,
        }
        return decision

    status = _v29_safe_upper(broker.get("status"), "UNKNOWN")
    freshness = _v31_broker_check_freshness(broker)
    decision["broker_check"]["freshness"] = freshness
    broker_blocked = status == "BLOCKED"
    broker_stale = freshness.get("ok") is not True
    if decision.get("final_state") == "ENTRY_READY" and (broker_blocked or broker_stale):
        blockers = list(decision.get("blockers") or [])
        if broker_blocked:
            blockers.append("BROKER_CHECK_BLOCKED")
            blockers.extend(broker.get("blockers") or [])
        if broker_stale:
            blockers.append("BROKER_CHECK_STALE")
            blockers.extend(freshness.get("blockers") or freshness.get("warnings") or [])
        deduped = []
        for blocker in blockers:
            if blocker and blocker not in deduped:
                deduped.append(blocker)
        decision["final_state"] = "RISK_BLOCKED"
        decision["decision"] = "RISK_BLOCKED"
        decision["main_blocker"] = "RISK_BLOCKED"
        decision["blockers"] = deduped
        decision["risk_status"] = "RISK_BLOCKED"
        decision["risk_blocker"] = "BROKER_CHECK_BLOCKED" if broker_blocked else "BROKER_CHECK_STALE"
        decision["manual_review_ready"] = False
        decision["explanation"] = (
            f"{decision.get('ticker')}: RISK_BLOCKED por broker_check. "
            "El contexto IBKR disponible no soporta este setup para revision manual o no esta fresco."
        )
    return decision


def _v31_finalize_decision_support_contract(decision):
    state = _v31_normalize_state(decision.get("final_state"))
    decision["final_state"] = state
    decision["decision"] = state
    decision["manual_review_ready"] = state == "ENTRY_READY"
    decision["can_operate"] = False
    decision["not_order_instruction"] = True
    warnings = list(decision.get("warnings") or [])
    for warning in ["DECISION_SUPPORT_ONLY", "MANUAL_REVIEW_REQUIRED", "NOT_AN_ORDER_INSTRUCTION"]:
        if warning not in warnings:
            warnings.append(warning)
    decision["warnings"] = warnings

    if state != "ENTRY_READY":
        decision["manual_review_ready"] = False
    if state == "ENTRY_READY":
        decision["main_blocker"] = None
        decision["blockers"] = []
    else:
        decision["main_blocker"] = _v31_main_blocker(state, decision.get("blockers") or [])

    contract = decision.get("selected_contract")
    if isinstance(contract, dict):
        contract["manual_review_ready"] = decision["manual_review_ready"]
        contract["can_operate"] = False
        contract["not_order_instruction"] = True
        decision["selected_contract"] = contract

    source = decision.get("source_decision")
    if isinstance(source, dict):
        source["can_operate"] = False
        decision["source_decision"] = source

    return decision


def _v31_apply_entry_evidence_gate(decision):
    if decision.get("final_state") != "ENTRY_READY":
        return decision

    decision = shared_evidence_quality.apply_evidence_quality(decision)
    gaps = shared_source_attribution.entry_ready_evidence_gaps(decision)
    quality = decision.get("evidence_quality") if isinstance(decision.get("evidence_quality"), dict) else {}
    decision["entry_evidence_gate"] = {
        "status": "PASS" if not gaps and quality.get("score", 0) >= shared_evidence_quality.ENTRY_READY_MIN_EVIDENCE_SCORE else "BLOCKED",
        "gaps": gaps,
        "evidence_quality_score": quality.get("score"),
        "evidence_quality_blockers": quality.get("blockers") or [],
        "minimum_evidence_quality_score": shared_evidence_quality.ENTRY_READY_MIN_EVIDENCE_SCORE,
        "required_contract_fields": list(shared_source_attribution.ENTRY_READY_REQUIRED_CONTRACT_FIELDS),
        "requires_candidate_source": True,
        "requires_confirmation_source": True,
        "manual_review_required": True,
        "execution_authorized": False,
        "not_order_instruction": True,
    }
    if not gaps and quality.get("score", 0) >= shared_evidence_quality.ENTRY_READY_MIN_EVIDENCE_SCORE:
        return decision

    wait_state = shared_source_attribution.entry_ready_evidence_wait_state(gaps) if gaps else shared_evidence_quality.evidence_quality_wait_state(quality)
    quality_blockers = quality.get("blockers") if isinstance(quality.get("blockers"), list) else []
    blockers = [wait_state, "ENTRY_EVIDENCE_GATE_FAILED", "EVIDENCE_QUALITY_TOO_LOW", *gaps, *quality_blockers]
    deduped = []
    for blocker in blockers:
        if blocker and blocker not in deduped:
            deduped.append(blocker)
    decision["final_state"] = wait_state
    decision["decision"] = wait_state
    decision["main_blocker"] = wait_state
    decision["blockers"] = deduped
    decision["manual_review_ready"] = False
    decision["can_operate"] = False
    if wait_state == "WAIT_TECHNICAL":
        decision["technical_status"] = "WAIT_TECHNICAL"
    if wait_state == "WAIT_OPTIONS_DATA":
        decision["construction_status"] = "WAIT_OPTIONS_DATA"
    decision["explanation"] = (
        f"{decision.get('ticker')}: {wait_state} por evidencia insuficiente para ENTRY_READY "
        f"(score={quality.get('score')}; gaps={', '.join(gaps or quality_blockers)})."
    )
    return _v31_finalize_decision_support_contract(decision)


def _v31_entry_ready_signal_seed(decision):
    contract = decision.get("selected_contract") or {}
    ticker = _v29_safe_upper(decision.get("ticker"), "UNKNOWN")
    strategy = _v29_safe_upper(decision.get("strategy"), "UNKNOWN")
    expiration = contract.get("expiration") or "NOEXP"
    strike = contract.get("strike") if contract.get("strike") is not None else "NOSTRIKE"
    generated_at = decision.get("generated_at") or _v29_now()
    signal_day = str(generated_at)[:10]
    signal_id = f"SIG-{signal_day}-{ticker}-{strategy}-{expiration}-{strike}"
    market = decision.get("market") if isinstance(decision.get("market"), dict) else {}
    market_regime = _strategy_market_regime(market)
    regime_policy = _strategy_regime_policy()
    regime_overlay = shared_strategy_regime_policy.regime_overlay(strategy, market_regime, regime_policy)
    recommendation = shared_daily_recommendations.recommendation_item(decision, 1)
    recommendation["regime_overlay"] = regime_overlay
    parameter_review = shared_strategy_regime_policy.parameter_review(recommendation, regime_overlay)
    exit_guidance = shared_strategy_exit_playbook.exit_overlay(
        {
            "ticker": ticker,
            "strategy": strategy,
            "market_regime": market_regime,
            "exit_state": "MONITOR",
            "position_open": None,
        },
        _strategy_exit_playbook(),
    )
    attribution = decision.get("source_attribution")
    if not isinstance(attribution, dict):
        attribution = shared_source_attribution.build_source_attribution(decision, decision.get("source_decision"))
    attribution = dict(attribution)
    attribution["signal_id"] = signal_id
    return {
        "id": signal_id,
        "outcome_id": signal_id,
        "signal_id": signal_id,
        "outcome_tracking_version": "v31_entry_ready_signal_outcome_v1",
        "outcome": "PENDING",
        "paper_outcome": True,
        "ticker": ticker,
        "strategy": strategy,
        "final_state": decision.get("final_state"),
        "decision_version": decision.get("decision_version"),
        "ruleset_version": decision.get("ruleset_version"),
        "snapshot_version": decision.get("snapshot_version"),
        "candidate_source": attribution.get("candidate_source"),
        "confirmation_source": attribution.get("confirmation_source"),
        "signal_source": attribution.get("signal_source"),
        "source_confidence": attribution.get("source_confidence"),
        "snapshot_id": attribution.get("snapshot_id"),
        "data_lineage": attribution.get("data_lineage"),
        "source_attribution": attribution,
        "recorded_at": generated_at,
        "entry_ready_at": generated_at,
        "market_regime": market_regime,
        "regime_detection": market.get("regime_detection") if isinstance(market.get("regime_detection"), dict) else {},
        "regime_overlay": regime_overlay,
        "parameter_review": parameter_review,
        "parameter_review_status": parameter_review.get("status"),
        "parameter_review_blockers": parameter_review.get("blockers") or [],
        "exit_regime_guidance": exit_guidance,
        "exit_regime_guidance_state": exit_guidance.get("regime_exit_guidance_state"),
        "selected_contract": {
            "strike": contract.get("strike"),
            "expiration": contract.get("expiration"),
            "dte": contract.get("dte"),
            "bid": contract.get("bid"),
            "ask": contract.get("ask"),
            "mid": contract.get("mid"),
            "spread": contract.get("spread"),
            "spread_pct": contract.get("spread_pct"),
            "delta": contract.get("delta"),
            "iv": contract.get("iv") or contract.get("implied_volatility"),
            "iv_rank": contract.get("iv_rank"),
            "historical_volatility": contract.get("historical_volatility"),
            "iv_hv_spread": contract.get("iv_hv_spread"),
            "volatility_context": contract.get("volatility_context") if isinstance(contract.get("volatility_context"), dict) else {},
            "volume": contract.get("volume"),
            "open_interest": contract.get("open_interest"),
            "option_market_data_source": contract.get("option_market_data_source") or contract.get("market_data_source"),
            "option_market_data_attempts": contract.get("option_market_data_attempts") or contract.get("market_data_attempts") or [],
            "option_discard_reasons": contract.get("option_discard_reasons") or [],
        },
        "measurement_plan": {
            "status": "PENDING_MARKET_FOLLOW_UP",
            "checkpoints": ["OPEN", "MIDDAY", "EOD", "PLUS_1D", "PLUS_5D", "EXPIRATION_OR_CLOSE"],
            "metrics": [
                "pnl_r",
                "mfe_r",
                "mae_r",
                "underlying_return_pct",
                "option_mid_change_pct",
                "max_favorable_excursion_r",
                "max_adverse_excursion_r",
            ],
            "exit_guidance_state": exit_guidance.get("regime_exit_guidance_state"),
            "exit_risk_action": (exit_guidance.get("regime_exit_adjustment") or {}).get("risk_action"),
        },
        "not_order_instruction": True,
    }


def _v31_track_entry_ready_signal(decision, source="v31"):
    if decision.get("final_state") != "ENTRY_READY":
        return {"enabled": False, "saved": False, "status": "NOT_ENTRY_READY"}
    seed = _v31_entry_ready_signal_seed(decision)
    durable = _journal_outcome(seed, source=f"{source}_entry_ready_signal")
    return {
        "enabled": True,
        "status": "TRACKED" if durable.get("saved") else durable.get("status", "TRACKING_ATTEMPTED"),
        "signal_id": seed.get("signal_id"),
        "outcome": seed,
        "durable_storage": durable,
        "not_order_instruction": True,
    }


_V31_MANUAL_REVIEW_VERSION = "v31_manual_review_journal_v1"
_V31_MANUAL_REVIEW_STATUSES = (
    "RECEIVED",
    "REVIEWING",
    "APPROVED_FOR_MANUAL_TRADE",
    "REJECTED",
    "WATCHLIST",
    "EXPIRED",
)


def _v31_manual_review_file():
    return _V29_RUNTIME_DIR / "v31_manual_review_journal.json"


def _v31_load_manual_reviews():
    data = _v29_load_json_file(_v31_manual_review_file())
    return data if isinstance(data, list) else []


def _v31_load_manual_reviews_with_durable(limit=500):
    try:
        limit = max(1, min(int(limit or 500), 1000))
    except Exception:
        limit = 500
    combined = []
    seen = set()
    durable = _durable_supabase_fetch("outcome", limit=limit)
    sources = {
        "local_count": 0,
        "durable_count": 0,
        "durable_available": durable is not None,
    }
    for source_name, items in [
        ("durable_count", durable if isinstance(durable, list) else []),
        ("local_count", _v31_load_manual_reviews()),
    ]:
        for item in items or []:
            if not isinstance(item, dict):
                continue
            if str(item.get("outcome_tracking_version") or "") != _V31_MANUAL_REVIEW_VERSION:
                continue
            key = item.get("review_id") or item.get("id") or item.get("outcome_id")
            if not key or key in seen:
                continue
            seen.add(key)
            combined.append(item)
            sources[source_name] = sources.get(source_name, 0) + 1
    return combined[-limit:], sources


def _v31_save_manual_reviews(items):
    path = _v31_manual_review_file()
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w") as f:
        json.dump((items or [])[-10000:], f, indent=2)
    return True


def _v31_manual_review_status(status):
    normalized = _v29_safe_upper(status, "")
    if normalized not in _V31_MANUAL_REVIEW_STATUSES:
        raise ValueError("INVALID_MANUAL_REVIEW_STATUS")
    return normalized


def _v31_manual_review_signal_id(decision, ticker):
    if isinstance(decision, dict) and decision.get("final_state") == "ENTRY_READY":
        return _v31_entry_ready_signal_seed(decision).get("signal_id")
    generated_day = _v29_now()[:10]
    return f"SIG-{generated_day}-{_v29_safe_upper(ticker, 'UNKNOWN')}-UNCONFIRMED"


def _v31_manual_review_decision_summary(decision):
    decision = decision if isinstance(decision, dict) else {}
    contract = decision.get("selected_contract") if isinstance(decision.get("selected_contract"), dict) else {}
    broker = decision.get("broker_check") if isinstance(decision.get("broker_check"), dict) else {}
    broker_freshness = broker.get("freshness") if isinstance(broker.get("freshness"), dict) else _v31_broker_check_freshness(broker)
    attribution = decision.get("source_attribution")
    if not isinstance(attribution, dict):
        attribution = shared_source_attribution.build_source_attribution(decision, decision.get("source_decision"))
    return {
        "ticker": decision.get("ticker"),
        "strategy": decision.get("strategy"),
        "final_state": decision.get("final_state"),
        "candidate_source": attribution.get("candidate_source"),
        "confirmation_source": attribution.get("confirmation_source"),
        "signal_source": attribution.get("signal_source"),
        "source_confidence": attribution.get("source_confidence"),
        "signal_id": attribution.get("signal_id"),
        "snapshot_id": attribution.get("snapshot_id"),
        "data_lineage": attribution.get("data_lineage"),
        "source_attribution": attribution,
        "main_blocker": decision.get("main_blocker"),
        "blockers": decision.get("blockers") or [],
        "technical_status": decision.get("technical_status"),
        "risk_status": decision.get("risk_status"),
        "manual_review_ready": decision.get("manual_review_ready") is True,
        "can_operate": False,
        "broker_check": {
            "broker_check_version": broker.get("broker_check_version"),
            "status": broker.get("status"),
            "ok_for_manual_review": broker.get("ok_for_manual_review"),
            "blockers": broker.get("blockers") or [],
            "warnings": broker.get("warnings") or [],
            "freshness": broker_freshness,
            "manual_broker_ticket_still_required": True,
            "execution_authorized": False,
            "not_order_instruction": True,
        },
        "selected_contract": {
            "strike": contract.get("strike"),
            "expiration": contract.get("expiration"),
            "dte": contract.get("dte"),
            "bid": contract.get("bid"),
            "ask": contract.get("ask"),
            "mid": contract.get("mid"),
            "spread": contract.get("spread"),
            "spread_pct": contract.get("spread_pct"),
            "delta": contract.get("delta"),
        },
        "not_order_instruction": True,
        "execution_authorized": False,
    }


def _v31_approval_contract_missing_fields(decision_summary):
    contract = decision_summary.get("selected_contract") if isinstance(decision_summary.get("selected_contract"), dict) else {}
    required = ["strike", "expiration", "dte", "bid", "ask", "mid", "spread", "spread_pct", "delta"]
    return [field for field in required if contract.get(field) in [None, "", "None"]]


def _v31_validate_manual_approval(decision_summary, reason, manual_broker_validation_override=False):
    if (
        decision_summary.get("final_state") != "ENTRY_READY"
        or decision_summary.get("manual_review_ready") is not True
    ):
        raise ValueError("APPROVAL_REQUIRES_ENTRY_READY")
    broker_summary = decision_summary.get("broker_check") if isinstance(decision_summary.get("broker_check"), dict) else {}
    broker_status = _v29_safe_upper(broker_summary.get("status"), "UNKNOWN")
    if broker_status == "BLOCKED":
        raise ValueError("APPROVAL_REQUIRES_BROKER_CHECK_NOT_BLOCKED")
    if broker_status == "UNKNOWN" and not manual_broker_validation_override:
        raise ValueError("APPROVAL_REQUIRES_BROKER_CHECK_AVAILABLE")
    if broker_status != "UNKNOWN":
        freshness = broker_summary.get("freshness") if isinstance(broker_summary.get("freshness"), dict) else _v31_broker_check_freshness(broker_summary)
        if freshness.get("ok") is not True:
            raise ValueError("APPROVAL_REQUIRES_FRESH_BROKER_CHECK")
    if _v29_safe_upper(decision_summary.get("technical_status"), "UNKNOWN") != "CONFIRMED":
        raise ValueError("APPROVAL_REQUIRES_CONFIRMED_TECHNICAL")
    if _v29_safe_upper(decision_summary.get("risk_status"), "UNKNOWN") != "PASS":
        raise ValueError("APPROVAL_REQUIRES_RISK_PASS")
    missing_contract = _v31_approval_contract_missing_fields(decision_summary)
    if missing_contract:
        raise ValueError("APPROVAL_REQUIRES_COMPLETE_CONTRACT")
    if not str(reason or "").strip():
        raise ValueError("APPROVAL_REQUIRES_REVIEW_REASON")
    return True


def _v31_manual_review_payload(payload):
    payload = payload if isinstance(payload, dict) else {}
    status = _v31_manual_review_status(payload.get("status") or "RECEIVED")
    ticker = _v29_safe_upper(payload.get("ticker"), "")
    decision = payload.get("decision") if isinstance(payload.get("decision"), dict) else None
    if not decision and ticker:
        decision = _v31_canonical_decision(ticker)
    if decision and not ticker:
        ticker = _v29_safe_upper(decision.get("ticker"), "")
    if not ticker:
        raise ValueError("MANUAL_REVIEW_TICKER_REQUIRED")

    now = _v29_now()
    signal_id = payload.get("signal_id") or _v31_manual_review_signal_id(decision, ticker)
    review_stamp = datetime.now(timezone.utc).strftime("%Y%m%d%H%M%S%f")
    review_id = payload.get("review_id") or f"MR-{signal_id}-{review_stamp}"
    actor = str(payload.get("actor") or "user")[:80]
    reason = str(payload.get("reason") or "")[:2000]
    manual_broker_validation_override = bool(payload.get("manual_broker_validation_override"))
    decision_summary = _v31_manual_review_decision_summary(decision)
    if status == "APPROVED_FOR_MANUAL_TRADE":
        _v31_validate_manual_approval(
            decision_summary,
            reason,
            manual_broker_validation_override=manual_broker_validation_override,
        )
    return {
        "id": review_id,
        "review_id": review_id,
        "signal_id": signal_id,
        "outcome_id": f"{signal_id}-MANUAL-REVIEW",
        "outcome_tracking_version": _V31_MANUAL_REVIEW_VERSION,
        "manual_review_version": _V31_MANUAL_REVIEW_VERSION,
        "recorded_at": now,
        "reviewed_at": now,
        "ticker": ticker,
        "strategy": decision_summary.get("strategy") or payload.get("strategy"),
        "candidate_source": decision_summary.get("candidate_source"),
        "confirmation_source": decision_summary.get("confirmation_source"),
        "signal_source": decision_summary.get("signal_source"),
        "source_confidence": decision_summary.get("source_confidence"),
        "snapshot_id": decision_summary.get("snapshot_id"),
        "data_lineage": decision_summary.get("data_lineage"),
        "status": status,
        "outcome": status,
        "reason": reason,
        "actor": actor,
        "source": str(payload.get("source") or "v31_manual_review")[:120],
        "decision": decision_summary,
        "allowed_statuses": list(_V31_MANUAL_REVIEW_STATUSES),
        "paper_outcome": True,
        "manual_trade_review_only": True,
        "manual_broker_validation_override": manual_broker_validation_override,
        "can_operate": False,
        "execution_authorized": False,
        "not_order_instruction": True,
        "disclaimer": (
            "Registro de revision humana para decision support. "
            "Stock Ultimus no coloca ordenes ni autoriza ejecucion automatica."
        ),
    }


def _v31_record_manual_review(payload):
    review = _v31_manual_review_payload(payload)
    items = _v31_load_manual_reviews()
    items.append(review)
    _v31_save_manual_reviews(items)
    durable_storage = _journal_outcome(review, source=review.get("source") or "v31_manual_review")
    audit_event = _record_audit_event(
        "V31_MANUAL_REVIEW_RECORDED",
        {
            "review_id": review.get("review_id"),
            "signal_id": review.get("signal_id"),
            "ticker": review.get("ticker"),
            "strategy": review.get("strategy"),
            "status": review.get("status"),
            "final_state": (review.get("decision") or {}).get("final_state"),
            "durable_saved": durable_storage.get("saved"),
            "execution_authorized": False,
            "not_order_instruction": True,
        },
        actor=review.get("actor") or "user",
        source=review.get("source") or "v31_manual_review",
    )
    return {
        "engine": "V31_MANUAL_REVIEW_JOURNAL",
        "status": "RECORDED",
        "review": review,
        "durable_storage": durable_storage,
        "audit_event": audit_event,
        "not_order_instruction": True,
        "execution_authorized": False,
    }


def _v31_manual_reviews_payload(limit=100):
    try:
        limit = max(1, min(int(limit), 1000))
    except Exception:
        limit = 100
    reviews, review_sources = _v31_load_manual_reviews_with_durable(limit=1000)
    recent = reviews[-limit:]
    by_status = {}
    latest_by_signal = {}
    for item in reviews:
        status = str(item.get("status") or "UNKNOWN").upper()
        by_status[status] = by_status.get(status, 0) + 1
        signal_id = item.get("signal_id")
        if signal_id:
            latest_by_signal[signal_id] = item
    return {
        "engine": "V31_MANUAL_REVIEW_JOURNAL",
        "manual_review_version": _V31_MANUAL_REVIEW_VERSION,
        "generated_at": _v29_now(),
        "allowed_statuses": list(_V31_MANUAL_REVIEW_STATUSES),
        "review_count": len(reviews),
        "by_status": dict(sorted(by_status.items())),
        "recent_reviews": recent,
        "latest_by_signal": latest_by_signal,
        "sources": review_sources,
        "durable_storage": _durable_storage_summary(),
        "not_order_instruction": True,
        "execution_authorized": False,
    }


def _v31_manual_review_console_decisions():
    decisions = _v31_all_decisions()
    actionable_states = {"ENTRY_READY", "RISK_BLOCKED", "WAIT_OPTIONS_DATA", "WAIT_TECHNICAL", "WAIT_MARKET"}
    visible = [d for d in decisions if d.get("final_state") in actionable_states or d.get("manual_review_ready") is True]
    reviews = _v31_manual_reviews_payload(limit=500)
    latest_by_signal = reviews.get("latest_by_signal") or {}
    enriched = []
    for decision in visible:
        ticker = _v29_safe_upper(decision.get("ticker"), "")
        signal_id = _v31_manual_review_signal_id(decision, ticker)
        item = dict(decision)
        item["manual_review_signal_id"] = signal_id
        item["latest_manual_review"] = latest_by_signal.get(signal_id)
        enriched.append(item)
    return enriched, reviews


def _v31_manual_review_status_badge(status):
    status = _v29_safe_upper(status, "UNREVIEWED")
    colors = {
        "APPROVED_FOR_MANUAL_TRADE": "#16a34a",
        "REJECTED": "#dc2626",
        "WATCHLIST": "#2563eb",
        "REVIEWING": "#d97706",
        "RECEIVED": "#64748b",
        "EXPIRED": "#475569",
        "UNREVIEWED": "#94a3b8",
    }
    return '<span class="badge" style="background:{color};">{status}</span>'.format(
        color=colors.get(status, "#64748b"),
        status=_v29_html_escape(status),
    )


def _v31_broker_status_badge(status):
    status = _v29_safe_upper(status, "UNKNOWN")
    colors = {
        "OK": "#16a34a",
        "WARNING": "#d97706",
        "BLOCKED": "#dc2626",
        "UNKNOWN": "#64748b",
    }
    return '<span class="badge" style="background:{color};">{status}</span>'.format(
        color=colors.get(status, "#64748b"),
        status=_v29_html_escape(status),
    )


def _v31_manual_review_action_forms(decision, action="/v31_manual_review_console/record", button_style="compact"):
    ticker = decision.get("ticker")
    state = decision.get("final_state")
    allowed = ["REVIEWING", "WATCHLIST", "REJECTED", "EXPIRED"]
    if state == "ENTRY_READY" and decision.get("manual_review_ready") is True:
        allowed.insert(1, "APPROVED_FOR_MANUAL_TRADE")
    labels = {
        "APPROVED_FOR_MANUAL_TRADE": "Approve manual",
        "REVIEWING": "Reviewing",
        "WATCHLIST": "Watchlist",
        "REJECTED": "Reject",
        "EXPIRED": "Expired",
    }
    reasons = {
        "APPROVED_FOR_MANUAL_TRADE": "Validé manualmente contrato, liquidez, spread, eventos, riesgo de cuenta y ticket en broker/TWS. Ejecución será manual.",
        "REVIEWING": "Iniciando revisión manual; validando chart, liquidez, riesgo y broker ticket.",
        "WATCHLIST": "Mantener en watchlist; falta mejor precio, confirmación o timing.",
        "REJECTED": "Descartada tras revisión manual.",
        "EXPIRED": "Setup expirado o ya no aplica.",
    }
    forms = []
    for status in allowed:
        css = "approve" if status == "APPROVED_FOR_MANUAL_TRADE" else status.lower()
        manual_broker_override = (
            '<input type="hidden" name="manual_broker_validation_override" value="true">'
            if status == "APPROVED_FOR_MANUAL_TRADE"
            else ""
        )
        forms.append("""
          <form method="post" action="{action}" class="action-form {button_style}">
            <input type="hidden" name="ticker" value="{ticker}">
            <input type="hidden" name="status" value="{status}">
            <input type="hidden" name="reason" value="{reason}">
            {manual_broker_override}
            <button class="{css}" type="submit">{label}</button>
          </form>
        """.format(
            action=_v29_html_escape(action),
            button_style=_v29_html_escape(button_style),
            ticker=_v29_html_escape(ticker),
            status=_v29_html_escape(status),
            reason=_v29_html_escape(reasons.get(status, "")),
            manual_broker_override=manual_broker_override,
            css=_v29_html_escape(css),
            label=_v29_html_escape(labels.get(status, status)),
        ))
    return "".join(forms)


def _v31_contract_alternatives_html(decision):
    alternatives = decision.get("contract_alternatives") if isinstance(decision.get("contract_alternatives"), list) else []
    if not alternatives:
        return ""
    rows = []
    for alt in alternatives[:3]:
        if not isinstance(alt, dict):
            continue
        rows.append("""
          <tr>
            <td>{strike}</td><td>{expiration}</td><td>{dte}</td>
            <td>{bid}/{ask}</td><td>{spread}</td><td>{spread_pct}</td><td>{delta}</td><td>{quality}</td>
          </tr>
        """.format(
            strike=_v29_html_escape(alt.get("strike")),
            expiration=_v29_html_escape(alt.get("expiration")),
            dte=_v29_html_escape(alt.get("dte")),
            bid=_v29_html_escape(alt.get("bid")),
            ask=_v29_html_escape(alt.get("ask")),
            spread=_v29_html_escape(alt.get("spread")),
            spread_pct=_v29_html_escape(alt.get("spread_pct")),
            delta=_v29_html_escape(alt.get("delta")),
            quality=_v29_html_escape(alt.get("quality")),
        ))
    if not rows:
        return ""
    return """
      <details class="alternatives">
        <summary>Alternativas de contrato para inspección</summary>
        <table>
          <thead><tr><th>Strike</th><th>Exp</th><th>DTE</th><th>Bid/Ask</th><th>Spread</th><th>Spread %</th><th>Delta</th><th>Quality</th></tr></thead>
          <tbody>{rows}</tbody>
        </table>
        <p>No cambian el estado ni autorizan operar; solo ayudan a revisar si conviene refrescar datos o inspeccionar otro contrato.</p>
      </details>
    """.format(rows="".join(rows))


def _v31_manual_review_inbox_cards(show_all=False):
    decisions, _ = _v31_manual_review_console_decisions()
    if not show_all:
        decisions = [
            item for item in decisions
            if item.get("final_state") == "ENTRY_READY" and item.get("manual_review_ready") is True
        ]
    reviewed_statuses = {"REVIEWING", "WATCHLIST", "REJECTED", "EXPIRED", "APPROVED_FOR_MANUAL_TRADE"}
    reviewed_count = 0
    cards = []
    for decision in decisions:
        contract = decision.get("selected_contract") or {}
        broker = decision.get("broker_check") if isinstance(decision.get("broker_check"), dict) else {}
        latest = decision.get("latest_manual_review") or {}
        latest_status = latest.get("status") or "UNREVIEWED"
        broker_status = _v29_safe_upper(broker.get("status"), "UNKNOWN")
        broker_note = ""
        if decision.get("final_state") == "ENTRY_READY" and decision.get("manual_review_ready") is True:
            if broker_status == "UNKNOWN":
                broker_note = (
                    "Broker UNKNOWN: Approve manual registra que validaste en TWS "
                    "contrato, liquidez, spread, eventos, riesgo de cuenta y ticket manual."
                )
            elif broker_status == "BLOCKED":
                broker_note = "Broker BLOCKED: no aprobar; revisa blockers antes de cualquier decisión."
            else:
                broker_note = "Approve manual registra revisión humana; no coloca ni autoriza órdenes."
        if _v29_safe_upper(latest_status, "UNREVIEWED") in reviewed_statuses:
            reviewed_count += 1
        cards.append("""
        <article class="setup-card">
          <header>
            <div>
              <a class="ticker" href="/v31_decision/{ticker}">{ticker}</a>
              <span class="strategy">{strategy}</span>
            </div>
            <div>{review_status}</div>
          </header>
          <div class="state-row">
            <span class="state">{state}</span>
            <span>{technical}</span>
            <span>{risk}</span>
            <span>{broker_status}</span>
          </div>
          <dl class="contract-grid">
            <div><dt>Strike</dt><dd>{strike}</dd></div>
            <div><dt>Exp</dt><dd>{expiration}</dd></div>
            <div><dt>DTE</dt><dd>{dte}</dd></div>
            <div><dt>Bid/Ask</dt><dd>{bid}/{ask}</dd></div>
            <div><dt>Spread %</dt><dd>{spread_pct}</dd></div>
            <div><dt>Delta</dt><dd>{delta}</dd></div>
          </dl>
          <p class="why">{why}</p>
          <p class="broker-note">{broker_note}</p>
          {alternatives_html}
          <div class="button-row">{forms}</div>
        </article>
        """.format(
            ticker=_v29_html_escape(decision.get("ticker")),
            strategy=_v29_html_escape(decision.get("strategy")),
            review_status=_v31_manual_review_status_badge(latest_status),
            state=_v29_html_escape(decision.get("final_state")),
            technical=_v29_html_escape(decision.get("technical_status")),
            risk=_v29_html_escape(decision.get("risk_status")),
            broker_status=_v29_html_escape("Broker " + broker_status),
            strike=_v29_html_escape(contract.get("strike")),
            expiration=_v29_html_escape(contract.get("expiration")),
            dte=_v29_html_escape(contract.get("dte")),
            bid=_v29_html_escape(contract.get("bid")),
            ask=_v29_html_escape(contract.get("ask")),
            spread_pct=_v29_html_escape(contract.get("spread_pct")),
            delta=_v29_html_escape(contract.get("delta")),
            why=_v29_html_escape(decision.get("explanation")),
            broker_note=_v29_html_escape(broker_note),
            alternatives_html=_v31_contract_alternatives_html(decision),
            forms=_v31_manual_review_action_forms(
                decision,
                action="/v31_manual_review_inbox/record",
                button_style="large",
            ),
        ))
    return cards, {
        "total": len(decisions),
        "reviewed": reviewed_count,
        "pending": max(len(decisions) - reviewed_count, 0),
    }


