def _strategy_market_regime(market):
    market = market if isinstance(market, dict) else {}
    raw = market.get("raw") if isinstance(market.get("raw"), dict) else {}
    detection = market.get("regime_detection") if isinstance(market.get("regime_detection"), dict) else {}
    detected = detection.get("market_regime")
    if detected:
        return detected

    for key in ["strategy_regime", "market_regime", "regime", "regime_id"]:
        value = market.get(key) or raw.get(key)
        if value:
            return value

    label = str(market.get("label") or raw.get("label") or raw.get("status") or "").upper()
    if "HIGH_VOL" in label or "EVENT" in label:
        return "HIGH_VOL_EVENT_RISK"
    if "INTRADAY_TREND" in label or "OPENING_RANGE" in label:
        return "INTRADAY_TREND"
    if "BEAR" in label or "CORRECTION" in label:
        return "BEARISH_OR_CORRECTION"
    if "BULL" in label and ("LOW_VOL" in label or "LOW VOL" in label):
        return "BULLISH_LOW_VOL"
    if "NEUTRAL" in label or "RANGE" in label:
        return "NEUTRAL_RANGE"
    return "UNKNOWN"


def _v31_runtime_file_status():
    files = []
    seen = set()
    for name in ["v28_master_snapshot.json", "v25_master_snapshot.json", *_V29_MASTER_FILES]:
        if name in seen:
            continue
        seen.add(name)
        path = _V29_RUNTIME_DIR / name
        item = {
            "path": str(path),
            "exists": path.exists(),
            "rows_found": 0,
            "technical_count": 0,
            "received_at": None,
            "generated_at": None,
            "source": None,
            "modified_at": None,
            "age_minutes": None,
        }
        if path.exists():
            try:
                modified = datetime.fromtimestamp(path.stat().st_mtime, tz=timezone.utc)
                item["modified_at"] = modified.isoformat()
                item["age_minutes"] = round((datetime.now(timezone.utc) - modified).total_seconds() / 60, 2)
            except Exception:
                pass
        data = _v29_load_json_file(path)
        if isinstance(data, dict):
            item["rows_found"] = len(_v29_extract_options_rows_from_obj(data))
            item["technical_count"] = len(_v29_extract_technical_from_obj(data))
            item["received_at"] = data.get("received_at")
            item["generated_at"] = data.get("generated_at")
            item["source"] = data.get("source")
        files.append(item)
    return files


def _v31_data_readiness_payload(status=None):
    status = status if isinstance(status, dict) else _v31_system_status_payload()
    summary = status.get("summary") if isinstance(status.get("summary"), dict) else {}
    rows_found = int(status.get("rows_found") or 0)
    technical_count = int(status.get("technical_count") or 0)
    total = int(summary.get("total") or 0)
    no_data = int(summary.get("no_data") or 0)
    state_summary_keys = [
        "entry_ready",
        "manual_review",
        "risk_blocked",
        "wait_options_data",
        "wait_technical",
        "wait_market",
        "wait_account_context",
        "no_data",
    ]
    dominant_state, dominant_state_count = max(
        ((key, int(summary.get(key) or 0)) for key in state_summary_keys if key in summary),
        key=lambda item: item[1],
        default=(None, 0),
    )
    wait_market = int(summary.get("wait_market") or 0)
    all_wait_market = bool(total) and wait_market == total
    runtime_files = _v31_runtime_file_status()
    existing_files = [item for item in runtime_files if item.get("exists")]
    newest = min(
        [item for item in existing_files if item.get("age_minutes") is not None],
        key=lambda item: item.get("age_minutes"),
        default=None,
    )
    newest_age = (newest or {}).get("age_minutes")
    stale_runtime = newest_age is None or newest_age > 90

    blockers = []
    if not status.get("master_snapshot_available"):
        blockers.append("MASTER_SNAPSHOT_MISSING")
    if rows_found == 0:
        blockers.append("NO_OPTION_ROWS")
    if technical_count == 0:
        blockers.append("NO_TECHNICAL_SNAPSHOT")
    if stale_runtime:
        blockers.append("RUNTIME_STALE_OR_UNKNOWN")
    if total and no_data == total:
        blockers.append("ALL_DEFAULT_TICKERS_NO_DATA")

    if total and no_data == total:
        diagnostic_status = "NO_DATA"
        explanation = "El motor esta conectado, pero no tiene datos ejecutables frescos para convertir el radar en oportunidades."
    elif all_wait_market and not blockers:
        diagnostic_status = "READY_FOR_DECISION_REVIEW"
        explanation = "El motor tiene datos, pero todos los candidatos estan esperando una ventana operativa confiable de mercado/opciones."
    elif blockers:
        diagnostic_status = "DEGRADED"
        explanation = "Hay datos parciales o desactualizados; se requiere refrescar fuentes antes de priorizar oportunidades."
    else:
        diagnostic_status = "READY_FOR_DECISION_REVIEW"
        explanation = "Hay snapshot y contexto suficientes para evaluar el ranking diario."

    next_actions = []
    if all_wait_market:
        next_actions.append("Reconsultar durante una ventana regular de mercado/opciones con bid/ask confiable; no convertir WAIT_MARKET en oportunidad accionable.")
    if stale_runtime or rows_found == 0:
        next_actions.append("Ejecutar ibkr_bridge.py durante una ventana valida de mercado/opciones y publicar /v31_ingest_snapshot.")
    if technical_count == 0:
        next_actions.append("Enviar alertas TradingView al webhook /technical_snapshot o confirmar que el forward test este activo.")
    if rows_found > 0 and technical_count > 0:
        next_actions.append("Revisar blockers por ticker en /gpt_v31_trade_decision/{ticker}.")
    if not next_actions:
        next_actions.append("Mantener monitoreo; no hay accion de orden autorizada.")

    return {
        "diagnostic_version": "v31_data_readiness_diagnostic_v1",
        "status": diagnostic_status,
        "explanation": explanation,
        "main_blocker": blockers[0] if blockers else None,
        "blockers": blockers,
        "master_snapshot_available": bool(status.get("master_snapshot_available")),
        "master_source": status.get("master_source"),
        "option_rows_found": rows_found,
        "technical_count": technical_count,
        "technical_tickers": status.get("technical_tickers") or [],
        "decision_state_counts": {
            key: summary.get(key)
            for key in state_summary_keys
            if key in summary
        },
        "dominant_state": dominant_state,
        "dominant_state_count": dominant_state_count,
        "wait_market_like_count": wait_market,
        "all_wait_market": all_wait_market,
        "operational_readiness": "WAIT_MARKET_WINDOW" if all_wait_market else diagnostic_status,
        "market": status.get("market") or {},
        "runtime_files": {
            "file_count": len(existing_files),
            "newest_file": (newest or {}).get("path"),
            "newest_age_minutes": newest_age,
            "files": runtime_files,
        },
        "next_required_actions": next_actions,
        "safe_to_invent_opportunities": False,
        "execution_authorized": False,
        "not_order_instruction": True,
    }


def _v31_gpt_daily_answer_guidance(payload, data_readiness):
    summary = payload.get("summary") if isinstance(payload.get("summary"), dict) else {}
    top_count = int(summary.get("manual_review_ready") or summary.get("entry_ready") or 0)
    all_wait_market = data_readiness.get("all_wait_market") is True
    if top_count > 0:
        lead = "Hay candidatos para revision manual. ENTRY_READY no autoriza ordenes."
    elif data_readiness.get("status") == "NO_DATA":
        lead = "No hay oportunidades disponibles porque faltan datos ejecutables frescos."
    elif all_wait_market:
        lead = "No hay oportunidades accionables ahora; el motor tiene datos, pero esta fuera de una ventana operativa confiable."
    else:
        lead = "No hay candidatos ENTRY_READY; revisar watchlist, bloqueadores y frescura."

    return {
        "guidance_version": "super_engine_bolsa_daily_answer_v1",
        "lead_message": lead,
        "must_call_action_first": True,
        "suggested_first_line": lead,
        "required_answer_sections": [
            "Estado del motor",
            "Oportunidades para revision manual",
            "Bloqueadas o en espera",
            "Datos faltantes y siguiente accion",
            "Nota de no autorizacion de ordenes",
        ],
        "when_no_data": {
            "say": "No hay oportunidades hoy con los datos actuales.",
            "include": [
                "diagnostico principal",
                "snapshot maestro disponible",
                "filas de opciones",
                "senales tecnicas",
                "acciones requeridas",
            ],
            "do_not_do": [
                "inventar tickers",
                "inferir precios",
                "proponer strikes",
                "marcar ENTRY_READY sin contrato ejecutable",
            ],
        },
        "when_wait_market": {
            "say": "No hay oportunidades accionables ahora; el motor tiene datos, pero esta fuera de una ventana operativa confiable.",
            "include": [
                "decision_state_counts",
                "wait_market_like_count",
                "market.label",
                "cantidad de filas de opciones",
                "cantidad de senales tecnicas",
                "siguiente hora o ventana recomendada para reconsultar",
            ],
            "do_not_do": [
                "usar Web Search para inventar oportunidades",
                "convertir WAIT_MARKET en ENTRY_READY",
                "sugerir ordenes por contexto general de mercado",
            ],
        },
        "manual_review_only": True,
        "execution_authorized": False,
        "not_order_instruction": True,
    }


_V31_DURABLE_SNAPSHOT_TABLE = "stock_ultimus_v31_snapshots"
_V31_DURABLE_RESTORE_STATE = {
    "attempted": False,
    "restored": False,
    "status": "NOT_ATTEMPTED",
}
_V31_DURABLE_PERSIST_STATE = {
    "enabled": supabase_enabled(),
    "saved": False,
    "status": "NOT_ATTEMPTED",
}


def _v31_durable_max_age_minutes():
    try:
        return max(1, int(V31_DURABLE_SNAPSHOT_MAX_AGE_MINUTES))
    except Exception:
        return 180


def _v31_parse_timestamp(value):
    if not value:
        return None
    try:
        text = str(value).strip().replace("Z", "+00:00")
        parsed = datetime.fromisoformat(text)
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)
    except Exception:
        return None


def _v31_snapshot_age_minutes(snapshot, durable_row=None):
    durable_row = durable_row or {}
    timestamp = (
        snapshot.get("received_at")
        or snapshot.get("generated_at")
        or durable_row.get("received_at")
        or durable_row.get("updated_at")
    )
    parsed = _v31_parse_timestamp(timestamp)
    if parsed is None:
        return None
    return round((datetime.now(timezone.utc) - parsed).total_seconds() / 60, 2)


def _v31_canonical_durable_payload(snapshot):
    snapshot = dict(snapshot or {})
    allowed_fields = [
        "engine",
        "source",
        "generated_at",
        "received_at",
        "snapshot_version",
        "options_rows",
        "technical_snapshot",
        "market",
        "tickers_detected",
        "rows_found",
        "technical_available",
        "bridge_status",
        "runtime_files_seen",
        "not_order_instruction",
    ]
    durable = {key: snapshot.get(key) for key in allowed_fields if key in snapshot}
    durable["options_rows"] = snapshot.get("options_rows") if isinstance(snapshot.get("options_rows"), list) else []
    durable["technical_snapshot"] = snapshot.get("technical_snapshot") if isinstance(snapshot.get("technical_snapshot"), dict) else {}
    durable["market"] = snapshot.get("market") if isinstance(snapshot.get("market"), dict) else {}
    durable["not_order_instruction"] = True
    return durable


def _v31_persist_durable_snapshot(snapshot):
    global _V31_DURABLE_PERSIST_STATE
    durable = _v31_canonical_durable_payload(snapshot)
    now = _v29_now()
    row = {
        "snapshot_id": V31_DURABLE_SNAPSHOT_ID,
        "snapshot_version": durable.get("snapshot_version") or "v30_options_executable_contract",
        "source": durable.get("source") or "UNKNOWN",
        "generated_at": durable.get("generated_at"),
        "received_at": durable.get("received_at") or now,
        "snapshot": durable,
        "not_order_instruction": True,
        "updated_at": now,
    }
    result = supabase_upsert_row(
        _V31_DURABLE_SNAPSHOT_TABLE,
        row,
        "snapshot_id",
    )
    result = dict(result or {})
    result["table"] = _V31_DURABLE_SNAPSHOT_TABLE
    result["snapshot_id"] = V31_DURABLE_SNAPSHOT_ID
    result["status"] = "SAVED" if result.get("saved") else "NOT_SAVED"
    _V31_DURABLE_PERSIST_STATE = result
    return result


def _v31_restore_durable_snapshot(force=False):
    global _V31_DURABLE_RESTORE_STATE
    if _V31_DURABLE_RESTORE_STATE.get("attempted") and not force:
        return dict(_V31_DURABLE_RESTORE_STATE)

    state = {
        "attempted": True,
        "restored": False,
        "status": "NOT_FOUND",
        "table": _V31_DURABLE_SNAPSHOT_TABLE,
        "snapshot_id": V31_DURABLE_SNAPSHOT_ID,
        "max_age_minutes": _v31_durable_max_age_minutes(),
    }

    if not supabase_enabled():
        state["status"] = "DISABLED"
        _V31_DURABLE_RESTORE_STATE = state
        return dict(state)

    row = supabase_fetch_single_row(
        _V31_DURABLE_SNAPSHOT_TABLE,
        {"snapshot_id": V31_DURABLE_SNAPSHOT_ID},
    )
    snapshot = row.get("snapshot") if isinstance(row, dict) else None
    if not isinstance(snapshot, dict):
        _V31_DURABLE_RESTORE_STATE = state
        return dict(state)

    age_minutes = _v31_snapshot_age_minutes(snapshot, row)
    state["age_minutes"] = age_minutes
    if age_minutes is None or age_minutes > state["max_age_minutes"]:
        state["status"] = "STALE"
        _V31_DURABLE_RESTORE_STATE = state
        return dict(state)

    restored = _v28_write_master(_v31_canonical_durable_payload(snapshot))
    state.update({
        "restored": True,
        "status": "RESTORED",
        "rows_found": restored.get("rows_found"),
        "technical_available": restored.get("technical_available"),
        "received_at": restored.get("received_at"),
    })
    _V31_DURABLE_RESTORE_STATE = state
    return dict(state)


def _v31_data_pipeline_status_payload():
    master = _v29_discover_master_snapshot()
    market = _v29_market_state(master)
    max_age = 10 if market.get("is_regular_market_open") else 240
    freshness = _v31_snapshot_freshness(master, max_age_minutes=max_age)
    status = _v31_system_status_payload()
    files = _v31_runtime_file_status()
    has_data = bool(status.get("master_snapshot_available"))
    return {
        "engine": "V31_DATA_PIPELINE_STATUS",
        "generated_at": _v29_now(),
        "status": "OK" if has_data else "NO_MASTER_SNAPSHOT",
        "canonical_ingest": "/v31_ingest_snapshot",
        "legacy_ingest_supported": "/v28_ingest_snapshot",
        "expected_bridge_target": "https://trading-engine-p097.onrender.com/v31_ingest_snapshot",
        "master_snapshot_available": has_data,
        "master_source": status.get("master_source"),
        "rows_found": status.get("rows_found"),
        "technical_count": status.get("technical_count"),
        "freshness": freshness,
        "runtime_files": files,
        "durable_snapshot": {
            "table": _V31_DURABLE_SNAPSHOT_TABLE,
            "restore": dict(_V31_DURABLE_RESTORE_STATE),
            "persist": dict(_V31_DURABLE_PERSIST_STATE),
            "max_age_minutes": _v31_durable_max_age_minutes(),
        },
        "diagnosis": (
            "Pipeline listo. Falta que ibkr_bridge.py publique un snapshot maestro."
            if not has_data else
            "Pipeline con snapshot maestro disponible para V31."
        ),
        "next_required_action": (
            "Ejecutar ibkr_bridge.py durante mercado o publicar POST /v31_ingest_snapshot con options_rows/technical_snapshot."
            if not has_data else
            "Validar decisiones V31 por ticker."
        ),
        "not_order_instruction": True,
    }


def _v31_ingest_snapshot_payload(payload, persist_durable=True, background_tasks=None):
    saved = _v28_write_master(payload)
    if persist_durable:
        durable_storage = _v31_persist_durable_snapshot(saved)
    elif background_tasks is not None:
        background_tasks.add_task(_v31_persist_durable_snapshot, saved)
        durable_storage = {
            "enabled": supabase_enabled(),
            "saved": False,
            "status": "QUEUED_BACKGROUND",
            "table": _V31_DURABLE_SNAPSHOT_TABLE,
            "snapshot_id": V31_DURABLE_SNAPSHOT_ID,
        }
    else:
        durable_storage = {
            "enabled": supabase_enabled(),
            "saved": False,
            "status": "SKIPPED",
            "table": _V31_DURABLE_SNAPSHOT_TABLE,
            "snapshot_id": V31_DURABLE_SNAPSHOT_ID,
        }
    return {
        "engine": "V31_CANONICAL_SNAPSHOT_INGEST",
        "status": "OK",
        "stored_file": str(_V28_MASTER_FILE),
        "alias_file": str(_V28_ALIAS_V25_FILE),
        "rows_found": saved.get("rows_found"),
        "technical_available": saved.get("technical_available"),
        "tickers_detected": saved.get("tickers_detected"),
        "received_at": saved.get("received_at"),
        "source": saved.get("source"),
        "durable_storage": durable_storage,
        "v31_status": "/v31_system_status",
        "v31_pipeline_status": "/v31_data_pipeline_status",
        "not_order_instruction": True,
    }


def _v31_record_snapshot_ingest_audit(result):
    _record_audit_event(
        "SNAPSHOT_INGESTED",
        {
            "source": result.get("source"),
            "rows_found": result.get("rows_found"),
            "technical_available": result.get("technical_available"),
            "durable_snapshot_saved": (result.get("durable_storage") or {}).get("saved"),
            "durable_snapshot_status": (result.get("durable_storage") or {}).get("status"),
            "not_order_instruction": True,
        },
        actor="bridge",
        source="v31_ingest_snapshot",
    )


def _v31_master_snapshot_timestamp(master):
    master = master if isinstance(master, dict) else {}
    data = master.get("data") if isinstance(master.get("data"), dict) else {}
    return (
        data.get("received_at")
        or data.get("generated_at")
        or data.get("remote_ingested_at")
        or data.get("updated_at")
    )


def _v31_snapshot_freshness(master, max_age_minutes=10):
    try:
        max_age_minutes = max(1, int(max_age_minutes))
    except Exception:
        max_age_minutes = 10

    master = master if isinstance(master, dict) else {}
    if not master.get("path"):
        return {
            "snapshot_freshness_version": "v31_snapshot_freshness_v1",
            "status": "MISSING",
            "ok": False,
            "timestamp": None,
            "age_minutes": None,
            "max_age_minutes": max_age_minutes,
            "stale_by_minutes": None,
            "detail": "No master snapshot is available.",
            "not_order_instruction": True,
        }

    timestamp = _v31_master_snapshot_timestamp(master)
    parsed = _v31_parse_timestamp(timestamp)
    if parsed is None:
        return {
            "snapshot_freshness_version": "v31_snapshot_freshness_v1",
            "status": "UNKNOWN",
            "ok": False,
            "timestamp": timestamp,
            "age_minutes": None,
            "max_age_minutes": max_age_minutes,
            "stale_by_minutes": None,
            "detail": "Master snapshot exists but has no parseable timestamp.",
            "not_order_instruction": True,
        }

    age_minutes = max(0, round((datetime.now(timezone.utc) - parsed).total_seconds() / 60, 2))
    stale_by = round(age_minutes - max_age_minutes, 2)
    is_fresh = age_minutes <= max_age_minutes
    return {
        "snapshot_freshness_version": "v31_snapshot_freshness_v1",
        "status": "FRESH" if is_fresh else "STALE",
        "ok": is_fresh,
        "timestamp": timestamp,
        "age_minutes": age_minutes,
        "max_age_minutes": max_age_minutes,
        "stale_by_minutes": max(stale_by, 0),
        "detail": (
            f"Snapshot age {age_minutes} minutes is within {max_age_minutes} minute limit."
            if is_fresh else
            f"Snapshot age {age_minutes} minutes exceeds {max_age_minutes} minute limit."
        ),
        "not_order_instruction": True,
    }


def _v31_trading_day_readiness_payload(
    max_open_snapshot_age_minutes=10,
    max_closed_snapshot_age_minutes=240,
):
    try:
        max_open_snapshot_age_minutes = max(1, int(max_open_snapshot_age_minutes))
    except Exception:
        max_open_snapshot_age_minutes = 10
    try:
        max_closed_snapshot_age_minutes = max(1, int(max_closed_snapshot_age_minutes))
    except Exception:
        max_closed_snapshot_age_minutes = 240

    master = _v29_discover_master_snapshot()
    market = _v29_market_state(master)
    market_open = bool(market.get("is_regular_market_open"))
    max_age = max_open_snapshot_age_minutes if market_open else max_closed_snapshot_age_minutes
    freshness = _v31_snapshot_freshness(master, max_age_minutes=max_age)
    production = _v31_production_readiness_payload()
    pipeline = _v31_data_pipeline_status_payload()
    monitor = _v31_monitor_status_payload()
    manual_reviews = _v31_manual_reviews_payload(limit=50)

    blockers = []
    warnings = []

    if production.get("status") != "READY":
        blockers.append("PRODUCTION_READINESS_BLOCKED")
    if pipeline.get("status") != "OK":
        if market_open:
            blockers.append("PIPELINE_NOT_READY_DURING_MARKET")
        else:
            warnings.append("PIPELINE_NOT_READY")
    if freshness.get("status") in {"MISSING", "UNKNOWN"}:
        if market_open:
            blockers.append(f"SNAPSHOT_{freshness.get('status')}")
        else:
            warnings.append(f"SNAPSHOT_{freshness.get('status')}")
    elif freshness.get("status") == "STALE":
        if market_open:
            blockers.append("STALE_SNAPSHOT")
        else:
            warnings.append("STALE_SNAPSHOT_OUTSIDE_MARKET")

    entry_ready_count = int((monitor.get("entry_ready_tickers") and len(monitor.get("entry_ready_tickers"))) or 0)
    manual_review_ready_count = int(monitor.get("manual_review_ready_count") or 0)
    risk_blocked_count = len(monitor.get("risk_blocked_tickers") or [])
    wait_options_count = len(monitor.get("wait_options_tickers") or [])

    if blockers:
        status = "ACTION_REQUIRED"
    elif pipeline.get("status") != "OK":
        status = "WAIT_PIPELINE"
    elif market.get("market_holiday"):
        status = "WAIT_MARKET"
    elif not market_open:
        status = "WAIT_MARKET"
    elif manual_review_ready_count > 0 or entry_ready_count > 0:
        status = "READY_FOR_MANUAL_REVIEW"
    else:
        status = "READY_FOR_TRADING_DAY"

    if status == "ACTION_REQUIRED":
        next_action = "Resolver blockers antes de confiar en decisiones V31."
    elif status == "WAIT_PIPELINE":
        next_action = "Publicar un snapshot maestro fresco desde el bridge/publicador."
    elif status == "WAIT_MARKET":
        next_action = "Esperar apertura regular del mercado estadounidense."
    elif status == "READY_FOR_MANUAL_REVIEW":
        next_action = "Revisar tickers ENTRY_READY manualmente; no es autorización de operar."
    else:
        next_action = "Sistema listo para monitoreo del trading day; esperar setups accionables."

    return {
        "engine": "V31_TRADING_DAY_READINESS",
        "trading_day_readiness_version": "v31_trading_day_readiness_v1",
        "generated_at": _v29_now(),
        "status": status,
        "blockers": blockers,
        "warnings": warnings,
        "next_required_action": next_action,
        "market": {
            "is_regular_market_open": market_open,
            "options_bidask_expected": bool(market.get("options_bidask_expected")),
            "market_holiday": bool(market.get("market_holiday")),
            "label": market.get("label"),
            "market_regime": market.get("market_regime"),
        },
        "freshness": freshness,
        "production_readiness": {
            "status": production.get("status"),
            "blocker_count": len(production.get("blockers") or []),
        },
        "pipeline": {
            "status": pipeline.get("status"),
            "master_snapshot_available": pipeline.get("master_snapshot_available"),
            "rows_found": pipeline.get("rows_found"),
            "technical_count": pipeline.get("technical_count"),
            "master_source": pipeline.get("master_source"),
        },
        "monitor": {
            "alert_level": monitor.get("alert_level"),
            "manual_review_ready_count": manual_review_ready_count,
            "entry_ready_tickers": monitor.get("entry_ready_tickers") or [],
            "risk_blocked_tickers": monitor.get("risk_blocked_tickers") or [],
            "wait_options_tickers": monitor.get("wait_options_tickers") or [],
        },
        "manual_reviews": {
            "review_count": manual_reviews.get("review_count"),
            "by_status": manual_reviews.get("by_status") or {},
        },
        "summary": {
            "entry_ready_count": entry_ready_count,
            "manual_review_ready_count": manual_review_ready_count,
            "risk_blocked_count": risk_blocked_count,
            "wait_options_count": wait_options_count,
            "ready_for_manual_review": status == "READY_FOR_MANUAL_REVIEW",
        },
        "decision_support_only": True,
        "manual_review_required": True,
        "not_order_instruction": True,
        "execution_authorized": False,
    }


def _v31_monitor_status_payload():
    pipeline = _v31_data_pipeline_status_payload()
    status = _v31_system_status_payload()
    decisions = status.get("decisions") or []
    summary = status.get("summary") or {}
    market = status.get("market") or {}

    entry_ready = [d for d in decisions if d.get("final_state") == "ENTRY_READY"]
    manual_ready = [d for d in decisions if d.get("manual_review_ready") is True]
    risk_blocked = [d for d in decisions if d.get("final_state") == "RISK_BLOCKED"]
    wait_options = [d for d in decisions if d.get("final_state") == "WAIT_OPTIONS_DATA"]
    wait_technical = [d for d in decisions if d.get("final_state") == "WAIT_TECHNICAL"]
    blocked_or_waiting_summaries = (
        [_v31_monitor_decision_summary(d) for d in risk_blocked]
        + [_v31_monitor_decision_summary(d) for d in wait_options]
        + [_v31_monitor_decision_summary(d) for d in wait_technical]
    )

    market_context = "REGULAR_MARKET_HOURS" if market.get("is_regular_market_open") else "OUTSIDE_MARKET_HOURS_OR_UNKNOWN"
    pipeline_status = pipeline.get("status")

    if entry_ready:
        alert_level = "ACTION_REQUIRED"
        message = "Hay setups ENTRY_READY para revision manual. No es instruccion de operar."
    elif risk_blocked:
        alert_level = "WARNING"
        message = "Hay setups bloqueados por riesgo. Revisar blockers antes de cualquier decision."
    elif pipeline_status != "OK" and market_context == "REGULAR_MARKET_HOURS":
        alert_level = "ACTION_REQUIRED"
        message = "Pipeline V31 sin snapshot maestro durante horario de mercado. Revisar bridge/publicador."
    elif pipeline_status != "OK":
        alert_level = "INFO"
        message = "Pipeline V31 sin snapshot maestro; no requiere accion inmediata fuera de mercado."
    elif wait_options:
        alert_level = "WARNING"
        message = "Pipeline V31 activo, pero faltan datos ejecutables de opciones en uno o mas tickers."
    elif wait_technical:
        alert_level = "WARNING"
        message = "Pipeline V31 activo, pero faltan confirmaciones tecnicas en uno o mas tickers."
    else:
        alert_level = "OK"
        message = "Pipeline V31 activo sin setups listos para revision manual."

    return {
        "engine": "V31_PIPELINE_MONITOR",
        "generated_at": _v29_now(),
        "alert_level": alert_level,
        "pipeline_status": pipeline_status,
        "market_context": market_context,
        "master_snapshot_available": pipeline.get("master_snapshot_available"),
        "master_source": pipeline.get("master_source"),
        "rows_found": pipeline.get("rows_found"),
        "technical_count": pipeline.get("technical_count"),
        "manual_review_ready_count": len(manual_ready),
        "entry_ready_tickers": [d.get("ticker") for d in entry_ready],
        "manual_review_ready_tickers": [d.get("ticker") for d in manual_ready],
        "risk_blocked_tickers": [d.get("ticker") for d in risk_blocked],
        "wait_options_tickers": [d.get("ticker") for d in wait_options],
        "wait_technical_tickers": [d.get("ticker") for d in wait_technical],
        "entry_ready_decisions": [_v31_monitor_decision_summary(d) for d in entry_ready],
        "risk_blocked_decisions": blocked_or_waiting_summaries[:len(risk_blocked)],
        "wait_options_decisions": blocked_or_waiting_summaries[len(risk_blocked):len(risk_blocked) + len(wait_options)],
        "wait_technical_decisions": blocked_or_waiting_summaries[len(risk_blocked) + len(wait_options):],
        "blocked_cause_groups": _v31_blocker_cause_summary(blocked_or_waiting_summaries),
        "summary": summary,
        "message": message,
        "next_required_action": pipeline.get("next_required_action"),
        "notification_sent": False,
        "notification_channel": None,
        "not_order_instruction": True,
    }


def _v31_monitor_decision_summary(decision):
    contract = decision.get("selected_contract") or {}
    risk_profile = decision.get("risk_profile") or {}
    broker = decision.get("broker_check") or {}
    option_diag = decision.get("option_data_diagnostic") if isinstance(decision.get("option_data_diagnostic"), dict) else {}
    risk_checks = risk_profile.get("blocked_checks") or decision.get("risk_blocked_details") or []
    summary = {
        "ticker": decision.get("ticker"),
        "final_state": decision.get("final_state"),
        "strategy": decision.get("strategy"),
        "main_blocker": decision.get("main_blocker"),
        "blockers": decision.get("blockers") or [],
        "risk_blocker": decision.get("risk_blocker") or risk_profile.get("primary_blocker"),
        "manual_review_ready": decision.get("manual_review_ready"),
        "can_operate": False,
        "technical_status": decision.get("technical_status"),
        "risk_status": decision.get("risk_status"),
        "construction_status": decision.get("construction_status"),
        "required_missing_fields": decision.get("required_missing_fields") or [],
        "risk_profile_status": risk_profile.get("status"),
        "risk_profile_blockers": risk_profile.get("blockers") or [],
        "risk_profile_blocked_checks": risk_checks,
        "broker_check_status": broker.get("status"),
        "broker_check_blockers": broker.get("blockers") or [],
        "broker_check_checks": broker.get("checks") or [],
        "option_data_diagnostic": option_diag,
        "contract": {
            "strike": contract.get("strike"),
            "expiration": contract.get("expiration"),
            "dte": contract.get("dte"),
            "bid": contract.get("bid"),
            "ask": contract.get("ask"),
            "mid": contract.get("mid"),
            "spread": contract.get("spread"),
            "spread_pct": contract.get("spread_pct"),
            "delta": contract.get("delta"),
        },
        "not_order_instruction": True,
    }
    summary["primary_block_reason"] = _v31_primary_block_reason(summary)
    return {
        key: value
        for key, value in summary.items()
        if value not in [None, [], {}]
    }


def _v31_monitor_should_notify(monitor, force=False):
    if force:
        return True, "FORCED"
    if monitor.get("alert_level") == "ACTION_REQUIRED":
        return True, "ACTION_REQUIRED"
    if int(monitor.get("manual_review_ready_count") or 0) > 0:
        return True, "MANUAL_REVIEW_READY"
    if monitor.get("alert_level") == "WARNING":
        return True, "BLOCKED_OR_WAITING_SUMMARY"
    return False, "NO_ACTIONABLE_ALERT"


def _v31_monitor_notify_cooldown_minutes():
    try:
        return max(1, int(os.getenv("V31_MONITOR_NOTIFY_COOLDOWN_MINUTES", "60") or "60"))
    except Exception:
        return 60


def _v31_monitor_notify_state_file():
    return _V29_RUNTIME_DIR / "v31_monitor_notify_state.json"


def _v31_monitor_alert_key(monitor):
    tickers = sorted(str(ticker).upper() for ticker in (monitor.get("entry_ready_tickers") or []) if ticker)
    risk_blocked = sorted(str(ticker).upper() for ticker in (monitor.get("risk_blocked_tickers") or []) if ticker)
    wait_options = sorted(str(ticker).upper() for ticker in (monitor.get("wait_options_tickers") or []) if ticker)
    wait_technical = sorted(str(ticker).upper() for ticker in (monitor.get("wait_technical_tickers") or []) if ticker)
    return "|".join([
        str(monitor.get("alert_level") or "UNKNOWN"),
        str(monitor.get("pipeline_status") or "UNKNOWN"),
        ",".join(tickers),
        ",".join(risk_blocked),
        ",".join(wait_options),
        ",".join(wait_technical),
    ])


def _v31_load_monitor_notify_state():
    return _v29_load_json_file(_v31_monitor_notify_state_file()) or {}


def _v31_save_monitor_notify_state(state):
    path = _v31_monitor_notify_state_file()
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w") as f:
        json.dump(state or {}, f, indent=2)
    return True


def _v31_monitor_dedupe_decision(monitor, force=False):
    alert_key = _v31_monitor_alert_key(monitor)
    cooldown = _v31_monitor_notify_cooldown_minutes()
    now = datetime.now(timezone.utc)
    state = _v31_load_monitor_notify_state()
    last = state.get(alert_key) if isinstance(state, dict) else None
    last_sent_at = (last or {}).get("sent_at") if isinstance(last, dict) else None
    last_dt = _v31_parse_timestamp(last_sent_at)
    elapsed_minutes = None
    if last_dt is not None:
        elapsed_minutes = round((now - last_dt).total_seconds() / 60, 2)
    deduped = bool(
        not force
        and last_dt is not None
        and elapsed_minutes is not None
        and elapsed_minutes < cooldown
    )
    return {
        "alert_key": alert_key,
        "cooldown_minutes": cooldown,
        "last_sent_at": last_sent_at,
        "elapsed_minutes": elapsed_minutes,
        "deduped": deduped,
        "not_order_instruction": True,
    }


def _v31_record_monitor_notification(monitor, notify_reason, status):
    alert_key = _v31_monitor_alert_key(monitor)
    state = _v31_load_monitor_notify_state()
    if not isinstance(state, dict):
        state = {}
    state[alert_key] = {
        "sent_at": _v29_now(),
        "notify_reason": notify_reason,
        "status": status,
        "alert_level": monitor.get("alert_level"),
        "entry_ready_tickers": monitor.get("entry_ready_tickers") or [],
        "manual_review_ready_count": monitor.get("manual_review_ready_count"),
        "not_order_instruction": True,
    }
    _v31_save_monitor_notify_state(state)
    return state[alert_key]


